        let binary_sha256 = binary_digest(&binary_path)?;
        let mut capture = Capture {
            binary: &binary_path,
            config_dir,
            bytes: 0,
            nodes: 0,
            deadline: Instant::now() + CAPTURE_TIMEOUT,
            commands: BTreeMap::new(),
