61:pub fn load(root: &File) -> Result<Inventory> {
62:    let bytes = read_file(root, GRAPH, 64 * 1024 * 1024)?;
63:    let graph_sha256 = format!("{:x}", Sha256::digest(&bytes));
64:    let manifest = String::from_utf8(read_file(root, "MANIFEST", 1024 * 1024)?)?;
65:    let hashes: Vec<_> = manifest.lines().filter_map(|l| l.strip_prefix("system-graph-sha256: ")).collect();
66:    ensure!(hashes == [graph_sha256.as_str()], "MANIFEST does not uniquely pin release graph");
67:    ensure!(manifest.lines().filter(|l| *l == format!("system-graph-path: {GRAPH}")).count() == 1, "MANIFEST graph path mismatch");
68:    let graph: GraphSnapshot = serde_json::from_slice(&bytes)?;
69:    ensure!(graph.format_version == 1 && graph.provenance.kind == GraphProvenanceKind::PreparedRelease, "not a prepared-release graph");
70:    ensure!(graph.nodes.len() <= 50_000 && graph.edges.len() <= 200_000, "graph bound exceeded");
71:    let mut ids = BTreeSet::new();
72:    let mut targets = Vec::new(); let mut entries = BTreeMap::new(); let mut services = BTreeMap::new();
73:    for node in graph.nodes {
74:        ensure!(ids.insert(node.id.clone()), "duplicate graph node");
75:        let value = serde_json::to_value(&node.attributes)?;
76:        match node.kind.as_str() {
77:            "release_target" => {
78:                let path = PathBuf::from(value["path"].as_str().context("target path absent")?);
79:                ensure!(node.id == format!("target:{}", path.display()), "target node ID mismatch");
80:                targets.push(Target { path, source: PathBuf::from(value["source"].as_str().context("target source absent")?),
81:                    noexec: value["noexec"].as_bool().context("target noexec absent")?, parent: None });
82:            }
83:            "prepared_path" => {
84:                let entry: Entry = serde_json::from_value(value)?;
85:                normalized(Path::new(&entry.path), false)?;
86:                ensure!(node.id == format!("file:{}", entry.path), "prepared node ID mismatch");
87:                ensure!(entries.insert(entry.path.clone(), entry).is_none(), "duplicate prepared path");
88:            }
89:            "runit_service" => {
90:                let name = node.id.strip_prefix("service:").context("service ID mismatch")?;
91:                service_name(name)?;
92:                let service: Service = serde_json::from_value(value)?;
93:                for dep in service.deps.iter().chain(&service.starts) { service_name(dep)?; }
94:                if let Some(probe) = &service.probe { ensure!(!probe.is_empty() && Path::new(&probe[0]).is_absolute(), "probe must be an absolute argv"); }
95:                services.insert(name.to_owned(), service);
96:            }
97:            _ => {}
98:        }
99:    }
100:    targets.sort_by(|a,b| a.path.components().count().cmp(&b.path.components().count()).then(a.path.cmp(&b.path)));
101:    validate_targets(&targets)?;
102:    for (name, s) in &services {
103:        for dep in s.deps.iter().chain(&s.starts) { ensure!(services.contains_key(dep), "{name} references undeclared service {dep}"); }
104:    }
105:    for entry in entries.values() {
106:        let t = targets.iter().find(|t| Path::new(&entry.path).starts_with(&t.source));
107:        ensure!(entry.release_target.as_deref() == t.and_then(|t| t.path.to_str()), "entry target attribution differs: {}", entry.path);
108:        for consumer in &entry.consumers {
109:            ensure!(services.get(consumer).is_some_and(|s| s.release_owned), "entry names non-release consumer {consumer}");
110:        }
111:        if protected(&entry.path) {
112:            ensure!(entry.sha256.is_none() && entry.hash_status.as_deref() == Some("protected_content_not_read"), "protected content was hashed");
113:            ensure!(entry.release_target.is_none(), "protected content cannot ship in a release target: {}", entry.path);
