27:fn service_path(name: &str) -> PathBuf { Path::new(SERVICES).join(name) }
28:pub fn linked(name: &str) -> Result<bool> {
29:    let path = Path::new(ENABLED).join(name);
30:    match std::fs::symlink_metadata(&path) {
31:        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(false),
32:        Err(e) => Err(e.into()),
33:        Ok(m) => { ensure!(m.file_type().is_symlink(), "enabled service is not a symlink: {name}"); Ok(true) }
34:    }
35:}
36:pub fn status(name: &str, newly_approved: bool) -> Result<Wanted> {
37:    inventory::service_name(name)?;
38:    let link = linked(name)?;
39:    let path = service_path(name);
40:    if link {
41:        ensure!(std::fs::canonicalize(Path::new(ENABLED).join(name))? == std::fs::canonicalize(&path)?,
42:            "enabled service {name} does not use /etc/sv; bootstrap must migrate its supervision without changing wanted state");
43:    }
44:    read_status(&path, link, newly_approved)
45:}
46:fn read_status(path: &Path, link: bool, newly_approved: bool) -> Result<Wanted> {
47:    let down = path.join("down").try_exists()?;
48:    let status = std::fs::read(path.join("supervise/status"));
49:    let bytes = match status {
50:        Ok(bytes) => bytes,
51:        Err(e) if e.kind() == std::io::ErrorKind::NotFound && !link => {
52:            return Ok(Wanted { pid: 0, start: [0; 12], paused: false,
53:                want: if newly_approved && !down { b'u' } else { b'd' }, state: 0, down, linked: false, new_service: newly_approved });
54:        }
55:        Err(e) => return Err(e).with_context(|| format!("read supervisor status at {}", path.display())),
56:    };
57:    ensure!(bytes.len() == 20 && matches!(bytes[17], b'u' | b'd') && bytes[19] <= 2, "invalid runit status at {}", path.display());
58:    let mut start = [0; 12]; start.copy_from_slice(&bytes[..12]);
59:    Ok(Wanted { pid: u32::from_le_bytes(bytes[12..16].try_into()?), start,
60:        paused: bytes[16] != 0, want: bytes[17], state: bytes[19], down, linked: link, new_service: false })
61:}
